import { Group, Mesh, PlaneGeometry, Vector3, Euler } from 'three/webgpu';
import {
    MeshBasicNodeMaterial,
    texture,
    color,
    uv,
    mix,
    mul,
    textureNode,
} from 'three/tsl';
import { gsap } from 'gsap';
import { createMSDFText } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {{x:number,y:number,z:number}} position
 * @property {{x:number,y:number,z:number}} rotation
 * @property {{x:number,y:number,z:number}} scale
 * @property {{imageUrl:string, depthMapUrl?:string, meshUrl?:string}} assets
 * @property {{textContent:string}} textContent
 */

/**
 * @typedef {Object} NodeContext
 * @property {(url:string)=>import('three/webgpu').Texture} textureLoader
 * @property {{[key:string]:(target:THREE.Object3D, params:any)=>void}} primitives
 * @property {{fontAtlas:any}} fontAtlas
 */

/**
 * Create a textured plane with headline text.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
    // Root container
    const root = new Group();
    root.position.set(
        config.position?.x ?? 0,
        config.position?.y ?? 0,
        config.position?.z ?? 0
    );
    root.rotation.set(
        config.rotation?.x ?? 0,
        config.rotation?.y ?? 0,
        config.rotation?.z ?? 0
    );
    root.scale.set(
        config.scale?.x ?? 1,
        config.scale?.y ?? 1,
        config.scale?.z ?? 1
    );

    // ----- Textured Plane -------------------------------------------------
    const tex = ctx.textureLoader(config.assets.imageUrl);
    tex.flipY = false; // keep orientation consistent with UVs

    // Preserve aspect ratio based on known source rect (512x320)
    const aspect = 512 / 320; // width / height
    const planeWidth = 1; // arbitrary unit width
    const planeHeight = planeWidth / aspect;

    const geometry = new PlaneGeometry(planeWidth, planeHeight);
    const material = new MeshBasicNodeMaterial();

    // Use node system to apply texture
    material.colorNode = texture(tex);
    material.alphaNode = texture(tex).a; // preserve alpha if any

    const planeMesh = new Mesh(geometry, material);
    planeMesh.position.set(0, 0, 0);
    root.add(planeMesh);

    // ----- Headline Text --------------------------------------------------
    const textString = config.textContent?.textContent ?? 'Pricing';
    const textColor = '#16161d'; // ink
    const textSize = 0.6; // scene‑unit height approximating design token (headline 0.34 em → scaled)
    const textMesh = createMSDFText(textString, {
        atlas: ctx.fontAtlas,
        font: 'Lora',
        size: textSize,
        color: textColor,
        // place text a little above the plane, centered
        position: new Vector3(0, planeHeight / 2 + 0.1, 0),
        // optional: alignment centre
        anchor: { x: 0.5, y: 0 },
    });
    root.add(textMesh);

    // ----- User Data -------------------------------------------------------
    root.userData.handlers = {}; // no interactive handlers for this node

    // Store disposables for cleanup
    const disposables = [
        geometry,
        material,
        tex,
        textMesh,
    ];

    // Store any GSAP timelines (none for this static node, but keep pattern)
    const timelines = [];

    root.userData.cleanup = () => {
        // Dispose Three.js resources
        disposables.forEach((obj) => {
            if (obj && typeof obj.dispose === 'function') {
                try {
                    obj.dispose();
                } catch (e) {
                    // ignore disposal errors
                }
            }
        });

        // Kill GSAP timelines
        timelines.forEach((tl) => tl.kill());
    };

    return root;
}
